import { combineReducers } from 'redux'
import {
  REQUEST_AUTH,
  RECEIVE_AUTH
} from '../actions/authActions'


function auth(
  state = {
    isFetching: false,
    didInvalidate: false,
    authResult: false
  },
  action
) {
  switch (action.type) {
    case REQUEST_AUTH:
      return Object.assign({}, state, {
        isFetching: true,
        didInvalidate: false
      })
    case RECEIVE_AUTH:
      return Object.assign({}, state, {
        isFetching: false,
        didInvalidate: false,
        authResult: action.authResult
      })
    default:
      return state
  }
}

const rootReducer = combineReducers({
  auth
})

export default rootReducer
